sp_CriarCliente	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarCliente`(\n\n    IN idEmpresa      INT,\n\n    IN nome           VARCHAR(150),\n\n    IN nomeFantasia   VARCHAR(150),\n\n    IN razaoSocial    VARCHAR(150),\n\n    IN cpfCNPJ        VARCHAR(18),\n\n    IN email          VARCHAR(255),\n\n    IN telefone       VARCHAR(20),\n\n    IN tipoCliente_id INT,\n\n    IN observacao     VARCHAR(500),\n\n    IN genero         CHAR(1),\n\n    IN enderecoId     INT,\n\n    IN dthNascimento  DATETIME,\n\n    IN fAtivo         TINYINT(1),\n\n    IN saldoDevedor   DECIMAL(20,2)\n\n)\nBEGIN\n\n    IF EXISTS (\n\n        SELECT 1 FROM Cliente\n\n        WHERE Cliente.idEmpresa = idEmpresa\n\n          AND CNPJ_CPF = cpfCNPJ\n\n          AND Cliente.fAtivo = 1\n\n    ) THEN\n\n        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'CPF/CNPJ já cadastrado para esta empresa.';\n\n    END IF;\n\n\n\n    INSERT INTO Cliente (idEmpresa, Nome, nomeFantasia, razaoSocial, saldoDevedor, CNPJ_CPF, Email, Telefone,\n\n                         tipoCliente_id, Observacao, Genero, enderecoId, dthCadastro, dthNascimento, fAtivo)\n\n    VALUES (idEmpresa, nome, nomeFantasia, razaoSocial, saldoDevedor, cpfCNPJ, email, telefone,\n\n            tipoCliente_id, observacao, genero, enderecoId, CURDATE(), dthNascimento, fAtivo);\n\n\n\n    SELECT LAST_INSERT_ID() AS idCliente;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
